package com.reservas.sk.bookings_service.adapters.out.security;

import com.reservas.sk.bookings_service.application.port.out.QrTokenData;
import com.reservas.sk.bookings_service.infrastructure.config.JwtProperties;
import org.junit.jupiter.api.BeforeEach;
import org.junit.jupiter.api.Test;

import static org.junit.jupiter.api.Assertions.*;

/**
 * Integration test to validate QR token compatibility between services.
 * This ensures that tokens generated by locations-service can be validated by bookings-service.
 * 
 * CRITICAL: This test validates the cross-service QR token contract.
 * If this test fails after changes, it means the two implementations are out of sync.
 */
class QrTokenCrossServiceCompatibilityTest {
    
    private JwtQrTokenGeneratorAdapter qrTokenGenerator;
    private JwtProperties jwtProperties;
    
    @BeforeEach
    void setUp() {
        jwtProperties = new JwtProperties();
        jwtProperties.setSecret("test-secret-key-for-cross-service-qr-token-validation-must-be-256bits");
        qrTokenGenerator = new JwtQrTokenGeneratorAdapter(jwtProperties);
    }
    
    @Test
    void shouldGenerateAndValidateQrToken_whenUsingConsistentConfiguration() {
        // Simulate: locations-service generates QR token for a space
        Long spaceId = 42L;
        String generatedToken = qrTokenGenerator.generateQrToken(spaceId);
        
        assertNotNull(generatedToken);
        assertFalse(generatedToken.isBlank());
        
        // Simulate: bookings-service validates the QR token during check-in
        QrTokenData validatedData = qrTokenGenerator.validateQrToken(generatedToken);
        
        // Verify token data matches
        assertEquals(spaceId, validatedData.spaceId(), 
            "SpaceId must match across service boundary");
        assertEquals("QR_CHECKIN", validatedData.tokenType(), 
            "TokenType must be QR_CHECKIN for compatibility");
        assertTrue(validatedData.issuedAt() > 0, 
            "IssuedAt timestamp must be present");
    }
    
    @Test
    void shouldValidateTokenStructure_whenGeneratedByLocationsService() {
        // This test ensures the token structure remains compatible
        Long spaceId = 123L;
        String token = qrTokenGenerator.generateQrToken(spaceId);
        
        // JWT tokens have 3 parts: header.payload.signature
        String[] parts = token.split("\\.");
        assertEquals(3, parts.length, 
            "JWT token must have exactly 3 parts (header.payload.signature)");
        
        // Validate can be parsed back
        assertDoesNotThrow(() -> qrTokenGenerator.validateQrToken(token),
            "Generated token must be valid and parseable");
    }
    
    @Test
    void shouldMaintainTokenPermanence_whenNoExpirationClaim() {
        // Verify QR tokens don't expire (critical for permanent space QR codes)
        Long spaceId = 999L;
        String token = qrTokenGenerator.generateQrToken(spaceId);
        
        // Wait a bit (simulating time passage)
        try {
            Thread.sleep(100);
        } catch (InterruptedException e) {
            Thread.currentThread().interrupt();
        }
        
        // Token should still be valid
        assertDoesNotThrow(() -> qrTokenGenerator.validateQrToken(token),
            "QR tokens must not expire (permanent per space)");
    }
    
    @Test
    void shouldRejectTokensFromDifferentSecret_whenSecretMismatch() {
        // Simulate a token generated with a different secret (security validation)
        String tokenWithWrongSecret = "eyJhbGciOiJIUzI1NiJ9.eyJzcGFjZUlkIjoxMjMsInRva2VuVHlwZSI6IlFSX0NIRUNLSU4iLCJpYXQiOjE3MTQ5OTI4MDB9.WrongSignatureHere";
        
        assertThrows(Exception.class, 
            () -> qrTokenGenerator.validateQrToken(tokenWithWrongSecret),
            "Tokens with invalid signature must be rejected");
    }
    
    /**
     * Regression test: Ensures critical claims are present and correctly named.
     * If this test fails, it indicates a breaking change in token structure.
     */
    @Test
    void shouldIncludeRequiredClaims_whenGeneratingToken() {
        Long spaceId = 456L;
        String token = qrTokenGenerator.generateQrToken(spaceId);
        QrTokenData data = qrTokenGenerator.validateQrToken(token);
        
        // Verify all critical claims are present
        assertNotNull(data.spaceId(), "spaceId claim is required");
        assertNotNull(data.tokenType(), "tokenType claim is required");
        assertTrue(data.issuedAt() > 0, "issuedAt claim is required");
        
        // Verify claim values match expectations
        assertEquals(spaceId, data.spaceId());
        assertEquals("QR_CHECKIN", data.tokenType());
    }
}
